static class Matriz{

    int[][] e;

    Matriz(int f,int c){
        e=new int[f][c];
    }

    Matriz(int[][] e){
        this.e=e;
    }

    int fil(){
        return e.length;
    }

    int col(){
        return e[0].length;
    }

    int get(int i,int j){
        return e[i][j];
    }

    public String toString(){

        String s="";

        for(int[] f:e){
            for(int x:f)
                s+=x+" ";

            s+="\n";
        }

        return s;
    }
}
